// `OPEN` is waiting on us. `AWAITING_USER` is waiting on you. `CLOSED` is finished.
//
// The state follows whoever spoke last and cannot be set directly.
// Ref: #/components/schemas/TicketStatus
type TicketStatus string

const (
	TicketStatusOPEN         TicketStatus = "OPEN"
	TicketStatusAWAITINGUSER TicketStatus = "AWAITING_USER"
	TicketStatusCLOSED       TicketStatus = "CLOSED"
)

// AllValues returns all TicketStatus values.
func (TicketStatus) AllValues() []TicketStatus {
	return []TicketStatus{
		TicketStatusOPEN,
		TicketStatusAWAITINGUSER,
		TicketStatusCLOSED,
	}
}

// MarshalText implements encoding.TextMarshaler.
func (s TicketStatus) MarshalText() ([]byte, error) {
	switch s {
	case TicketStatusOPEN:
		return []byte(s), nil
	case TicketStatusAWAITINGUSER:
		return []byte(s), nil
	case TicketStatusCLOSED:
		return []byte(s), nil
	default:
		return nil, errors.Errorf("invalid value: %q", s)
	}
}

// UnmarshalText implements encoding.TextUnmarshaler.
func (s *TicketStatus) UnmarshalText(data []byte) error {
	switch TicketStatus(data) {
	case TicketStatusOPEN:
		*s = TicketStatusOPEN
		return nil
	case TicketStatusAWAITINGUSER:
		*s = TicketStatusAWAITINGUSER
		return nil
	case TicketStatusCLOSED:
		*s = TicketStatusCLOSED
		return nil
	default:
		return errors.Errorf("invalid value: %q", data)
	}
}

type UploadAttachmentReq struct {
	Data io.Reader
}

// Read reads data from the Data reader.
//
// Kept to satisfy the io.Reader interface.
func (s UploadAttachmentReq) Read(p []byte) (n int, err error) {
	if s.Data == nil {
		return 0, io.EOF
	}
	return s.Data.Read(p)
}
